[{"order":1,"type":"heading","text":"HTTP Servers, Clients, and Middleware in Go"},{"order":2,"type":"paragraph","text":"Go provides a robust, production-ready standard library for building HTTP servers and clients without requiring external frameworks. In this tutorial, we will explore how to set up an HTTP server, create custom middleware, and consume APIs using Go's standard net/http package."},{"order":3,"type":"subheading","text":"1. Building a Basic HTTP Server"},{"order":4,"type":"paragraph","text":"The net/http package makes it simple to spin up a web server. We define handler functions to process incoming requests and write responses."},{"order":5,"type":"code","text":"package main

import (
	"fmt"
	"net/http"
)

func helloHandler(w http.ResponseWriter, r *http.Request) {
	fmt.Fprintf(w, "Hello, World!")
}

func main() {
	http.HandleFunc("/hello", helloHandler)
	fmt.Println("Server listening on port 8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		fmt.Printf("Server failed: %v\n", err)
	}
}"},{"order":6,"type":"subheading","text":"2. Creating HTTP Middleware"},{"order":7,"type":"paragraph","text":"Middleware in Go is typically implemented as a function that takes an http.Handler and returns an http.Handler. This pattern allows us to inject behavior such as logging, authentication, and panic recovery before the request reaches the final handler."},{"order":8,"type":"code","text":"package main

import (
	"log"
	"net/http"
	"time"
)

// LoggingMiddleware records the execution time of each HTTP request.
func LoggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		log.Printf("Started %s %s", r.Method, r.URL.Path)

		next.ServeHTTP(w, r)

		log.Printf("Completed in %v", time.Since(start))
	})
}"},{"order":9,"type":"subheading","text":"3. Consuming APIs with the HTTP Client"},{"order":10,"type":"paragraph","text":"Go also supplies a robust HTTP client out of the box via http.Client. For production use, it is best practice to configure a custom client timeout instead of using http.DefaultClient."},{"order":11,"type":"code","text":"package main

import (
	"fmt"
	"io"
	"net/http"
	"time"
)

func main() {
	client := &http.Client{
		Timeout: 10 * time.Second,
	}

	resp, err := client.Get("https://api.github.com/zen")
	if err != nil {
		fmt.Printf("Error making request: %v\n", err)
		return
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(resp.Body)
	if err != nil {
		fmt.Printf("Error reading response: %v\n", err)
		return
	}

	fmt.Printf("Zen: %s\n", string(body))
}"},{"order":12,"type":"subheading","text":"Summary of Best Practices"},{"order":13,"type":"bullet_point","text":"Always set timeouts on http.Client to prevent hanging goroutines."},{"order":14,"type":"bullet_point","text":"Always close response bodies using defer resp.Body.Close() to avoid memory leaks."},{"order":15,"type":"bullet_point","text":"Use standard http.Handler wrapping for chainable middleware operations."}]
